                AdditionalTab::Properties => {
                    for_all_tabs!(focused, t, t.display_display(self.world, ui));
                }
                AdditionalTab::Export => {
                    for_all_tabs!(focused, t, t.export_display(self.world, ui));
                }
            }
        });
        Default::default()
    }
