#[derive(Serialize, Deserialize, Clone, Default, MapEntities, PartialEq)]
pub(crate) struct SettingsTab;

impl Tab for SettingsTab {
    const NAME: &'static str = "Settings";
    fn main_display(&mut self, world: &mut World, ui: &mut Ui) {
        if let Err(e) = world.run_system_cached_with(show_settings, ui) {
            bevy::log::error!("UI Error while displaying settings page: {}", e)
        }
        #[cfg(not(target_arch = "wasm32"))]
        if let Err(e) = world.run_system_cached_with(show_mod_settings, ui) {
            bevy::log::error!("UI Error while displaying mod settings: {}", e)
        }
    }
    fn title(&self) -> egui::WidgetText {
        tr!("tab-settings").into()
    }
}

fn show_settings(
    InMut(ui): InMut<Ui>,
    mut preferences: ResMut<UserPreferences>,
    mut settings: ResMut<ProjectSettings>,
) {
    ui.heading(tr!("settings-preferences"));
    egui::Grid::new("settings grid 1").show(ui, |ui| {
        ui.label(tr!("settings-dark-mode"));
        ui.checkbox(&mut preferences.dark_mode, "");
        ui.end_row();

        ui.label(tr!("settings-language"));
        egui::ComboBox::new("language", "")
            .selected_text(preferences.lang.name())
            .show_ui(ui, |ui| {
                for lang in Language::ALL {
                    ui.selectable_value(&mut preferences.lang, *lang, lang.name());
                }
            });
        ui.end_row();

        ui.label(tr!("settings-developer-mode"));
        ui.checkbox(&mut preferences.developer_mode, "");
        ui.end_row();

        ui.label(tr!("settings-antialiasing-options"));
        egui::ComboBox::new("antialiasing", "")
            .selected_text(match preferences.antialiasing_mode {
                AntialiasingMode::Off => tr!("settings-off"),
                AntialiasingMode::On => tr!("settings-on"),
            })
            .show_ui(ui, |ui| {
                ui.selectable_value(
                    &mut preferences.antialiasing_mode,
                    AntialiasingMode::Off,
                    tr!("settings-off"),
                );
                ui.selectable_value(
                    &mut preferences.antialiasing_mode,
                    AntialiasingMode::On,
                    tr!("settings-on"),
                );
            });
        ui.end_row();

        ui.label(tr!("settings-lod-mode"));
        egui::ComboBox::new("lod", "")
            .selected_text(match preferences.level_of_detail_mode {
                LevelOfDetailMode::Off => tr!("settings-off"),
                LevelOfDetailMode::Lod2 => tr!("settings-lod-2x"),
                LevelOfDetailMode::Lod4 => tr!("settings-lod-4x"),
            })
            .show_ui(ui, |ui| {
                ui.selectable_value(
                    &mut preferences.level_of_detail_mode,
                    LevelOfDetailMode::Off,
                    tr!("settings-off"),
                );
                ui.selectable_value(
                    &mut preferences.level_of_detail_mode,
                    LevelOfDetailMode::Lod2,
                    tr!("settings-lod-2x"),
                );
                ui.selectable_value(
                    &mut preferences.level_of_detail_mode,
                    LevelOfDetailMode::Lod4,
                    tr!("settings-lod-4x"),
                );
            });
        ui.end_row();
    });
    ui.heading(tr!("settings-project-settings"));
    ui.text_edit_multiline(&mut settings.remarks);
}

/// Mod management section — only compiled on native targets.
#[cfg(not(target_arch = "wasm32"))]
fn show_mod_settings(
    InMut(ui): InMut<Ui>,
    mut preferences: ResMut<UserPreferences>,
    mut action_queue: ResMut<ModActionQueue>,
    available: Res<AvailableMods>,
    registry: Res<ModNameRegistry>,
) {
    ui.separator();
    ui.heading(tr!("settings-mods"));

    if available.mods.is_empty() {
        ui.label(tr!("settings-no-mods-found"));
        return;
    }

    for mod_entry in &available.mods {
        // Display name derived from file path — no dedicated field.
        let display_name = std::path::Path::new(&mod_entry.path)
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or("unknown");

        // A mod is considered enabled if its path is in the registry
        // (meaning it has been successfully loaded).
        let is_loaded = registry.path_to_name.contains_key(&mod_entry.path);
        let mut enabled = is_loaded || preferences.enabled_mods.contains(&mod_entry.path);
        let prev = enabled;

        ui.checkbox(&mut enabled, display_name);
        if enabled && !prev {
            preferences.enabled_mods.push(mod_entry.path.clone());
            action_queue.push(ModAction::Load(mod_entry.path.clone()));
        } else if !enabled && prev {
            preferences.enabled_mods.retain(|p| p != &mod_entry.path);
            // Resolve the actual mod name for unloading.
            if let Some(actual_name) = registry.path_to_name.get(&mod_entry.path) {
                action_queue.push(ModAction::Unload(actual_name.clone()));
            }
        }
    }
}

use bevy_moder_sdk::{component, resource, message};

#[component]
pub struct Square(pub bevy_math::Vec2);

#[component]
pub struct Rect(pub bevy_math::IVec2);

#[resource]
pub struct Player(pub bevy_math::Vec2);

#[message]
pub struct HostGreeting(pub String);

#[message]
pub struct ModReply(pub String);

//! SDK traits and re-exports for shared type definitions.
//!
//! Types defined with [`#[component]`](macro@bevy_moder_sdk_macros::component)
//! or [`#[resource]`](macro@bevy_moder_sdk_macros::resource) in this crate
//! can be serialised and exchanged between the host and WASM mods.

pub use bevy_moder_sdk_macros::*;
pub use serde;

/// Trait for components that can be queried by mods.
///
/// Implemented automatically by the `#[component]` macro.
pub trait Component {
    /// Returns the component ID (equal to the struct name).
    fn component_id() -> &'static str;
}

//! Shared types for FFI between bevy-moder host and WASM mods.
//!
//! These types are `#[repr(C)]` and must be compatible with the WASM32 target,
//! where pointers and `usize` are 32-bit.

/// System info: metadata for a mod system exported to the host.
#[repr(C)]
#[derive(Debug)]
pub struct SystemInfo {
    /// The exported function name (null-terminated C string).
    pub export_name: [u8; 64],
    /// 0 = Update, 1 = Startup.
    pub schedule: u8,
}

/// Result passed between WASM mod and host after a query.
///
/// Pointers and lengths are `u32` for WASM32 compatibility.
#[repr(C)]
#[derive(Debug)]
pub struct HostModResult {
    /// Pointer to serialized data (in WASM linear memory).
    pub data_ptr: u32,
    /// Length of the serialized data.
    pub data_len: u32,
}

//! SDK macros for defining shared types between host and mod.
//!
//! These macros mark structs that can be serialised and exchanged between
//! the Bevy host and WASM mods.  The **struct name** is used as the
//! component / resource ID — the old `id = "..."` attribute has been
//! removed to avoid redundancy and naming drift.

extern crate proc_macro;

use proc_macro::TokenStream;
use quote::quote;
use syn::{parse_macro_input, DeriveInput};

/// Mark a struct as a **component** that mods can query from the host.
///
/// The struct name becomes the component ID.  If two types end up with the
/// same ID the host will **panic** at startup with a clear error message.
///
/// # Example
/// ```ignore
/// #[component]
/// pub struct Square(pub Vec2);
/// // id = "Square"
/// ```
#[proc_macro_attribute]
pub fn component(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);
    let struct_name = &derive_input.ident;
    let component_id = struct_name.to_string();

    let expanded = quote! {
        #[derive(::bevy_moder_sdk::serde::Serialize, ::bevy_moder_sdk::serde::Deserialize)]
        #[serde(crate = "::bevy_moder_sdk::serde")]
        #derive_input

        impl bevy_moder_sdk::Component for #struct_name {
            fn component_id() -> &'static str {
                #component_id
            }
        }
    };

    TokenStream::from(expanded)
}

/// Mark a struct as a **message** that can be sent between host and mod.
///
/// Adds `Serialize` / `Deserialize` derives so the type can cross the
/// FFI boundary.  The host must also register it with
/// [`#[register_message]`](bevy_moder_runtime_macros::register_message)
/// to make it available as a Bevy `Message`.
///
/// # Example
/// ```ignore
/// #[message]
/// pub struct HostGreeting(pub String);
/// ```
#[proc_macro_attribute]
pub fn message(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);

    let expanded = quote! {
        #[derive(::bevy_moder_sdk::serde::Serialize, ::bevy_moder_sdk::serde::Deserialize)]
        #[serde(crate = "::bevy_moder_sdk::serde")]
        #derive_input
    };

    TokenStream::from(expanded)
}

/// Mark a struct as a **resource** that mods can read from the host.
///
/// The struct name becomes the resource ID.
///
/// # Example
/// ```ignore
/// #[resource]
/// pub struct Player(pub Vec2);
/// // id = "Player"
/// ```
#[proc_macro_attribute]
pub fn resource(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);
    let struct_name = &derive_input.ident;
    let resource_id = struct_name.to_string();

    let expanded = quote! {
        #[derive(::bevy_moder_sdk::serde::Serialize, ::bevy_moder_sdk::serde::Deserialize)]
        #[serde(crate = "::bevy_moder_sdk::serde")]
        #derive_input

        impl #struct_name {
            /// Get the resource ID (matches the struct name).
            pub const fn resource_id() -> &'static str {
