三个 crate 全部编译通过，零错误。

## 实现总结

### 创建的文件

| 文件 | 内容 |
|---|---|
| `crates/paiagram-sdk/src/ui.rs` | SDK 侧的 UI 组件类型（`#[component]`）：`ModTab`, `Container`, `Label`, `Button`, `Checkbox`, `TextEdit`, `CollapsingHeader`, `Separator`, `Slider` + `ContainerLayout` 枚举 |
| `crates/paiagram-ui/src/mod_ui.rs` | Host 侧注册类型（`#[register_component]`，与 SDK 镜像）、树收集、egui 渲染、交互回写 |
| `crates/paiagram-ui/src/tabs/mod_tab.rs` | `ModTabWidget` struct + `Tab` trait 实现，三阶段渲染（收集→渲染→回写） |

### 修改的文件

| 文件 | 变更 |
|---|---|
| `crates/paiagram-sdk/src/lib.rs` | 加 `pub mod ui;` |
| `crates/paiagram-ui/src/tabs.rs` | 加 `mod mod_tab;`、`all_tabs` 导出 `ModTabWidget` |
| `crates/paiagram-ui/src/lib.rs` | 加 `mod mod_ui;`、`MainTab::ModTab(ModTabWidget)` 变体、更新 `for_all_tabs!`/`for_all_tab_types!` 宏、加 `sync_mod_tabs` 系统 |
| `crates/paiagram-ui/Cargo.toml` | 加 `ctor.workspace = true`（条件 native） |
| `Cargo.toml`（workspace） | 加 `ctor = "0.4"` |

### Mod 使用方式

```rust
use paiagram_sdk::ui::*;
use bevy_moder_api::*;

mod_def!("my_mod");

#[system(schedule = Startup)]
fn init() {
    spawn!(ModTab { tab_id: "my".into(), title: "My Mod".into() });
    spawn!(Container { node_id: "root".into(), tab_id: "my".into(),
           parent_node_id: None, layout: Column });
    spawn!(Label { node_id: "lbl".into(), tab_id: "my".into(),
           parent_node_id: Some("root".into()), text: "Hello".into() });
    spawn!(Button { node_id: "btn".into(), tab_id: "my".into(),
           parent_node_id: Some("root".into()), text: "Click".into(), clicked: false });
}

#[system(schedule = Update)]
fn update() {
    for button in query_mut!(Button) {
        if button.clicked {
            log_info!("Button was clicked!");
            button.clicked = false;  // Host 置 true，Mod 读取后重置
        }
    }
}
```

### 交互流程

```
User 点击 egui 按钮
  → Host 写 Button.clicked = true 到实体
  → 下一帧 Mod 通过 query_mut!(Button) 读到
  → Mod 处理 → 重置 clicked = false
```

use bevy_moder_api::*;
use paiagram_sdk::ui::*;

mod_def!("openttd");

#[system(schedule = Startup)]
fn init() {
    spawn!(ModTab {
        tab_id: "my".into(),
        title: "My Mod".into()
    });
    spawn!(Container {
        node_id: "root".into(),
        tab_id: "my".into(),
        parent_node_id: None,
        layout: ContainerLayout::Column
    });
    spawn!(Label {
        node_id: "lbl".into(),
        tab_id: "my".into(),
        parent_node_id: Some("root".into()),
        text: "Hello".into()
    });
    spawn!(Button {
        node_id: "btn".into(),
        tab_id: "my".into(),
        parent_node_id: Some("root".into()),
        text: "Click".into(),
        clicked: false
    });
}

#[system(schedule = Update)]
fn update() {
    for button in query_mut!(Button).iter_mut() {
        if button.0.clicked {
            log_info!("Button was clicked!");
            button.0.clicked = false;
        }
    }
}

/// Query entities that have all the listed components.
///
/// Returns an iterator of `(Component1, Component2, …)` tuples.
/// On error, logs the problem and returns an empty iterator (never panics).
#[macro_export]
macro_rules! query {
    ($($component:ty),+ $(,)?) => {{
        let components: Vec<($($component,)+)> = 'query: {
            let component_ids: Vec<&str> = vec![$(<$component>::component_id()),+];

            let serialized_ids = match bincode::serde::encode_to_vec(
                &component_ids, bincode::config::standard(),
            ) {
                Ok(v) => v,
                Err(e) => {
                    $crate::log_error!("query! encode component IDs failed: {}", e);
                    break 'query Vec::new();
                }
            };

            let mut result = $crate::HostModResult {
                data_ptr: 0,
                data_len: 0,
            };
            let result_ptr = &mut result as *mut $crate::HostModResult as *mut u8;

            let data_len = unsafe {
                $crate::__mod_query_components(
                    serialized_ids.as_ptr(),
                    serialized_ids.len(),
                    result_ptr,
                )
            };

            let mut components: Vec<($($component,)+)> = Vec::new();

            if data_len > 0 && result.data_ptr != 0 {
                let data_slice = unsafe {
                    std::slice::from_raw_parts(
                        result.data_ptr as *const u8,
                        result.data_len as usize,
                    )
                };

                if let Ok((entities, _)) =
                    bincode::serde::decode_from_slice::<Vec<(u64, Vec<Vec<u8>>)>, _>(
                        data_slice, bincode::config::standard(),
                    )
                {
                    let expected_count = {
                        let mut n = 0;
                        $(let _ = stringify!($component); n += 1;)+
                        n
                    };

                    for (_entity_id, ser_comps) in entities {
                        if ser_comps.len() != expected_count {
                            continue;
                        }

                        let mut idx = 0;
                        let tuple = (
                            $(match bincode::serde::decode_from_slice::<$component, _>(
                                &ser_comps[{ let v = idx; idx += 1; v }],
                                bincode::config::standard(),
                            ) {
                                Ok((v, _)) => v,
                                Err(e) => {
                                    $crate::log_error!(
                                        "query! decode {} failed: {}",
                                        stringify!($component), e,
                                    );
                                    continue;
                                }
                            },)+
                        );
                        components.push(tuple);
                    }
                }

                unsafe {
                    $crate::__mod_free_memory(
                        result.data_ptr as *mut u8,
                        result.data_len as usize,
                    );
                }
            }

            components
        };

        components.into_iter()
    }};
}

/// Query entities with mutable access for modification.
///
/// Returns a `QueryMutGuard` that provides `iter_mut()` and automatically
/// writes back changed components to the host when dropped.
///
/// # Example
/// ```ignore
/// let mut q = query_mut!(Square, Rect);
/// for (square, rect) in q.iter_mut() {
///     square.0 = Vec2::new(10.0, 20.0);
/// }
/// // guard dropped → modified entities written back
/// ```
#[macro_export]
macro_rules! query_mut {
    ($($component:ty),+ $(,)?) => {{
        let component_ids: Vec<&str> = vec![$(<$component>::component_id()),+];

        'build: {
            let serialized_ids = match bincode::serde::encode_to_vec(
                &component_ids, bincode::config::standard(),
            ) {
                Ok(v) => v,
                Err(e) => {
                    $crate::log_error!("query_mut! encode component IDs failed: {}", e);
                    break 'build $crate::QueryMutGuard::new(
                        Vec::new(), Vec::new(), component_ids,
                    );
                }
            };

            let mut result = $crate::HostModResult { data_ptr: 0, data_len: 0 };
        let result_ptr = &mut result as *mut $crate::HostModResult as *mut u8;

        let data_len = unsafe {
            $crate::__mod_query_components(
                serialized_ids.as_ptr(),
                serialized_ids.len(),
                result_ptr,
            )
        };

        let mut items: Vec<($($component,)+)> = Vec::new();
        let mut entity_ids: Vec<u64> = Vec::new();

        if data_len > 0 && result.data_ptr != 0 {
            let data_slice = unsafe {
                std::slice::from_raw_parts(
                    result.data_ptr as *const u8,
                    result.data_len as usize,
                )
            };

            if let Ok((entities, _)) =
                bincode::serde::decode_from_slice::<Vec<(u64, Vec<Vec<u8>>)>, _>(
                    data_slice, bincode::config::standard(),
                )
            {
                let expected_count = {
                    let mut n = 0;
                    $(let _ = stringify!($component); n += 1;)+
                    n
                };

                for (entity_id, ser_comps) in entities {
                    if ser_comps.len() != expected_count {
                        continue;
                    }

                    let mut idx = 0;
                    let tuple = (
                        $(match bincode::serde::decode_from_slice::<$component, _>(
                            &ser_comps[{ let v = idx; idx += 1; v }],
                            bincode::config::standard(),
                        ) {
                            Ok((v, _)) => v,
                            Err(_) => continue,
                        },)+
                    );
                    items.push(tuple);
                    entity_ids.push(entity_id);
                }
            }

            unsafe {
                $crate::__mod_free_memory(
                    result.data_ptr as *mut u8,
                    result.data_len as usize,
                );
            }
        }

        let component_ids_owned: Vec<&'static str> = vec![$(<$component>::component_id()),+];
        break 'build $crate::QueryMutGuard::new(items, entity_ids, component_ids_owned);
    }}
    };
}

