//! Per-component serialization for tuples.
//!
//! `ComponentFlatten` is implemented for tuples up to 12 elements.
//! It splits a tuple `(A, B, C)` into `[bytes(A), bytes(B), bytes(C)]`.

use serde::Serialize;

/// Trait for splitting a tuple of components into individually serialized blobs.
pub trait ComponentFlatten {
    fn flatten_components(&self) -> Vec<Vec<u8>>;
}

macro_rules! impl_flatten_n {
    // Base case — emit one impl block for N fields.
    //
    // Usage:
    //   impl_flatten_n!(2; 0, 1; T0, T1);

    // Recursive arm: builds the Serialize-bounded generic params
