fn parse_schedule_args(args: TokenStream) -> u8 {
    let args_str = args.to_string();
    if args_str.is_empty() {
        return 0;
    }

    let parsed: Vec<&str> = args_str.split('=').collect();
    if parsed.len() != 2 {
        return 0;
    }
    let key = parsed[0].trim();
    let value = parsed[1].trim();

    if key != "schedule" {
        return 0;
    }
    match value {
        "Update" => 0,
        "Startup" => 1,
        _ => 0,
    }
}

