            let mut buf = [0u8; #name_bytes_len];
            let src = #name_str.as_bytes();
            let mut i = 0;
            while i < src.len() {
                buf[i] = src[i];
                i += 1;
            }
            buf
        };

        #[unsafe(no_mangle)]
        pub extern "C" fn __mod_get_name() -> *const u8 {
            __MOD_NAME_BUF.as_ptr()
