            bevy_moder_api::system_count()
        }

        #[unsafe(no_mangle)]
        pub extern "C" fn __mod_get_systems_names_ptr() -> *const u8 {
            let entries = bevy_moder_api::system_name_entries();
            entries.as_ptr() as *const u8
        }

        #[allow(non_snake_case)]
        #[::bevy_moder_api::ctor::ctor]
        fn __mod_ctor_set_mod_name() {
            bevy_moder_api::set_mod_name(#name_str);
        }

        #[unsafe(no_mangle)]
        pub extern "C" fn __mod_get_mod_components_count() -> usize {
            bevy_moder_api::mod_component_count()
        }

        #[unsafe(no_mangle)]
