            let entries = bevy_moder_api::mod_component_name_entries();
            entries.as_ptr() as *const u8
        }

        #[unsafe(no_mangle)]
        pub extern "C" fn __mod_get_mod_resources_count() -> usize {
            bevy_moder_api::mod_resource_count()
        }

