    if let Ok(a) = unsafe { unty::<S, u8>(s) } {
        println!("It is an u8 with value {a}");
    } else {
        println!("it is not an u8");
    }
}
foo(10u8); // will print "it is an u8"
foo("test"); // will print "it is not an u8"
```

Note that both of these functions may give false positives if both types have lifetimes. There currently is not a way to prevent this. See [`type_equal`](fn.type_equal.html "fn unty::type_equal") for more information.

