        ui.menu_button(tr!("menu-text"), |ui| {
            if ui.button(tr!("menu-new-text-message")).clicked() {
                self.world.spawn((
                    TextMessage(String::new()),
                    Name::new(tr!("menu-new-message")),
                ));
