                    }
                });
                if world.resource::<UserPreferences>().developer_mode {
                    let mut frame_time_history = world.resource_mut::<FrameTimeHistory>();
                    frame_time_history.push(ui.input(|r| r.stable_dt));
                    let average_dt = frame_time_history.average_dt();
                    ui.monospace(format!("FPS: {:6.2}", 1.0_f32 / average_dt));
                    ui.monospace(format!("FRAME: {:5.2}ms", average_dt * 1000.0_f32));
                    ui.monospace(format!(
                        "CPU: {:5.2}ms",
                        cpu_time.unwrap_or(0.0) * 1000.0_f32
                    ));
                    ui.horizontal(|ui| {
                        const GAP: f32 = 4.0;
                        const SAMPLE_COUNT: usize = 32;
                        let stroke = Stroke {
                            color: PredefinedColor::Blue.get(ui.visuals().dark_mode),
                            width: 3.0,
                        };
                        let max = frame_time_history
                            .previous_n(SAMPLE_COUNT)
                            .fold(0.0_f32, f32::max)
                            .max(f32::EPSILON);
                        let graph_width = SAMPLE_COUNT as f32 * (stroke.width + GAP) - GAP;
                        let graph_height = ui.available_height();
                        let (rect, _) = ui.allocate_exact_size(
                            egui::vec2(graph_width, graph_height),
                            egui::Sense::hover(),
                        );
                        for (idx, f) in frame_time_history.previous_n(SAMPLE_COUNT).enumerate() {
                            let height = rect.height() * (f / max).clamp(0.0, 1.0);
                            let x = rect.right()
                                - idx as f32 * (stroke.width + GAP)
                                - stroke.width * 0.5;
                            let points = [
                                egui::pos2(x, rect.bottom()),
                                egui::pos2(x, rect.bottom() - height),
                            ];
                            ui.painter().line_segment(points, stroke);
                        }
                    });
                }
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    world.resource_scope(|world, mut history: Mut<actions::ActionHistory>| {
                        if ui
                            .add_enabled(history.can_undo(), egui::Button::new(tr!("menu-undo")))
                            .clicked()
                        {
                            history.try_undo(world);
                        }
                        if ui
                            .add_enabled(history.can_redo(), egui::Button::new(tr!("menu-redo")))
                            .clicked()
                        {
                            history.try_redo(world);
                        }
                    });
                    let mut aus = world.resource_mut::<AdditionalUiState>();
                    ui.checkbox(&mut aus.expanded, "");
                });
            })
        });
    Panel::bottom("bottom panel")
        .exact_size(24.0)
        .show_inside(ui, |ui| {
            ui.horizontal_centered(|ui| {
                let ticks_in_cycle = world
                    .resource::<ProjectSettings>()
                    .repeat_frequency
                    .to_ticks();
                let mut timer = world.resource_mut::<GlobalTimer>();
                let mut time = timer.read_ticks().to_timetable_time();
                ui.add_enabled(
                    !timer.sync_to_real_time,
                    egui::Checkbox::new(&mut timer.animation_playing, ""),
                );
                let time_response = ui.add(TimeDragValue(&mut time));
                ui.add_enabled(
                    !timer.sync_to_real_time,
                    egui::DragValue::new(&mut timer.animation_speed)
                        .fixed_decimals(1)
                        .suffix("×"),
                );
                egui::Popup::menu(&time_response).show(|ui| {
                    ui.checkbox(&mut timer.sync_to_real_time, tr!("menu-sync-system-clock"));
                });
                if !timer.sync_to_real_time
                    && time_response.dragged()
                    && timer.try_lock(Entity::PLACEHOLDER)
                {
                    timer.write_ticks(Tick::from_timetable_time(time));
                } else {
                    timer.try_unlock(Entity::PLACEHOLDER);
                }
                if timer.animation_playing {
                    ui.ctx().request_repaint();
                }

                // cycle progress bar
                // don't allocate a painter here instead directly use ui's painter
                // to avoid the content from being clipped
                let (_id, rect) = ui.allocate_space(ui.available_size());
                let progress_stroke = ui.visuals().window_stroke();
                ui.painter()
                    .hline(rect.x_range(), rect.center().y, progress_stroke);
                let amount_of_ticks = 24;
                for i in 0..(amount_of_ticks + 1) {
                    let progress = (1.0 / amount_of_ticks as f32) * i as f32;
                    let x = rect.left().lerp(rect.right(), progress);
                    let y_range = if i % 4 == 0 {
                        rect.y_range()
                    } else {
                        rect.y_range().shrink(5.0)
                    };
                    ui.painter().vline(x, y_range, progress_stroke);
                }
                let indicator_stroke = Stroke::new(1.5, Color32::RED);
                let progress = timer.read_ticks().normalized_with(ticks_in_cycle);
                let progress = progress.0 as f32 / ticks_in_cycle.0 as f32;
                ui.painter().vline(
                    rect.left().lerp(rect.right(), progress),
                    rect.y_range(),
                    indicator_stroke,
                );
            })
        });
    world.resource_scope(|world, mut aus: Mut<AdditionalUiState>| {
        world.resource_scope(|mut world, mut mus: Mut<MainUiState>| {
            let mut tab_viewer = AdditionalTabViewer {
                world: &mut world,
                focused_tab: aus
                    .focused_id
                    .and_then(|id| mus.tiles.get_mut(id))
                    .and_then(|p| {
                        if let Tile::Pane(pane) = p {
                            Some(pane)
                        } else {
                            None
                        }
                    }),
            };
            Panel::right("right panel")
                .frame(Frame::default())
                .show_animated_inside(ui, aus.expanded, |ui| {
                    aus.ui(&mut tab_viewer, ui);
                });
            egui::CentralPanel::default()
                .frame(Frame::default())
                .show_inside(ui, |ui| {
                    let mut maximized = mus.maximized;
                    if let Some(max_id) = mus.maximized
                        && let Some(Tile::Pane(pane)) = mus.tree.tiles.get_mut(max_id)
                    {
                        let mut tab_viewer = MainTabViewer {
                            world: &mut world,
                            last_focused_id: &mut None,
                            last_maximized_id: &mut None,
                        };
                        Panel::top("maximized_top")
                            .exact_size(24.0)
                            .show_inside(ui, |ui| {
                                let res = ui.horizontal(|ui| {
                                    ui.label(tab_viewer.tab_title_for_pane(pane));
                                    ui.label(RichText::new(tr!("menu-maximized-view")).italics());
                                    ui.with_layout(
                                        egui::Layout::right_to_left(egui::Align::Center),
                                        |ui| ui.button("x"),
                                    )
                                    .inner
                                });
                                if res.inner.clicked() {
                                    maximized = None
                                }
                            });
                        let _ = tab_viewer.pane_ui(ui, max_id, pane);
                    } else {
                        let mut tab_viewer = MainTabViewer {
                            world: &mut world,
                            last_focused_id: &mut aus.focused_id,
                            last_maximized_id: &mut maximized,
                        };
                        mus.tree.ui(&mut tab_viewer, ui);
                    }
                    mus.maximized = maximized;
                });
        })
    });
}

/// Sync `ModTab` ECS entities with dynamic tabs in `MainUiState`.
#[cfg(not(target_arch = "wasm32"))]
fn sync_mod_tabs(
    mod_tab_query: Query<&mod_ui::ModTab>,
    mut main_ui: ResMut<MainUiState>,
) {
    use std::collections::{HashMap, HashSet};

    let desired: HashMap<String, String> = mod_tab_query
        .iter()
        .map(|t| (t.tab_id.clone(), t.title.clone()))
        .collect();

    // Remove stale tabs.
    let stale: Vec<egui_tiles::TileId> = main_ui
        .tree
        .tiles
        .iter()
        .filter_map(|(id, tile)| {
            if let egui_tiles::Tile::Pane(MainTab::ModTab(w)) = tile {
                if !desired.contains_key(&w.tab_id) {
                    return Some(*id);
                }
            }
            None
        })
        .collect();

    for id in stale {
        main_ui.tree.tiles.remove(id);
    }

    // Update titles and collect existing tab IDs.
    let mut existing: HashSet<String> = HashSet::new();
    for (_, tile) in main_ui.tree.tiles.iter_mut() {
        if let egui_tiles::Tile::Pane(MainTab::ModTab(w)) = tile {
            existing.insert(w.tab_id.clone());
            if let Some(new_title) = desired.get(&w.tab_id) {
                if &w.title != new_title {
                    w.title = new_title.clone();
                }
            }
        }
    }

    // Add new tabs.
    for (tab_id, title) in &desired {
        if !existing.contains(tab_id) {
            main_ui.push_to_focused_leaf(MainTab::ModTab(ModTabWidget {
                tab_id: tab_id.clone(),
                title: title.clone(),
            }));
        }
    }
}

fn sync_ui(InRef(ctx): InRef<Context>, preferences: Res<UserPreferences>) {
    if !preferences.is_changed() {
        return;
    }
    if preferences.dark_mode {
        ctx.set_theme(egui::Theme::Dark);
    } else {
        ctx.set_theme(egui::Theme::Light);
    }
}

pub fn apply_custom_fonts(ctx: &Context) {
    #[cfg(not(target_arch = "wasm32"))]
    {
        let sarasa = load_sarasa_local();
        ctx.set_fonts(build_font_definitions(sarasa));
    }

    #[cfg(target_arch = "wasm32")]
    {
        ctx.set_fonts(build_font_definitions(None));
        download_sarasa_and_apply(ctx.clone());
    }
}

fn build_font_definitions(sarasa: Option<Vec<u8>>) -> egui::FontDefinitions {
    let mut fonts = egui::FontDefinitions::default();

    let has_sarasa = sarasa.is_some();
    if let Some(bytes) = sarasa {
        fonts.font_data.insert(
            "my_font".to_owned(),
            std::sync::Arc::new(egui::FontData::from_owned(bytes)),
        );
    }

    // FIX: i dont know why ws add 'assets/fonts' to git ignore so i'll just comment this out
    // fonts.font_data.insert(
    //     "dia_pro".to_owned(),
    //     std::sync::Arc::new(egui::FontData::from_static(include_bytes!(
    //         "../assets/fonts/DiaPro-Regular.ttf"
    //     ))),
    // );

    if has_sarasa {
        fonts
            .families
            .get_mut(&egui::FontFamily::Proportional)
            .unwrap()
            .insert(0, "my_font".to_owned());
    }

    let mut dia_pro_family = vec!["dia_pro".to_owned()];
    if has_sarasa {
        dia_pro_family.push("my_font".to_owned());
    }
    fonts
        .families
        .insert(egui::FontFamily::Name("dia_pro".into()), dia_pro_family);

    fonts
}

#[cfg(not(target_arch = "wasm32"))]
fn load_sarasa_local() -> Option<Vec<u8>> {
    let mut candidates = vec![
        PathBuf::from("assets/fonts/SarasaUiSC-Regular.ttf"),
        PathBuf::from("crates/paiagram-ui/assets/fonts/SarasaUiSC-Regular.ttf"),
    ];

    if let Ok(exe) = std::env::current_exe()
        && let Some(parent) = exe.parent()
    {
        candidates.push(parent.join("assets/fonts/SarasaUiSC-Regular.ttf"));
    }

    for path in candidates {
        if let Ok(bytes) = std::fs::read(&path) {
            return Some(bytes);
        }
    }

    None
}

#[cfg(target_arch = "wasm32")]
fn download_sarasa_and_apply(ctx: Context) {
    wasm_bindgen_futures::spawn_local(async move {
        let Some(window) = eframe::web_sys::window() else {
            return;
        };

        let Ok(response) =
            wasm_bindgen_futures::JsFuture::from(window.fetch_with_str("SarasaUiSC-Regular.ttf"))
                .await
        else {
            return;
        };

        let Ok(response) = response.dyn_into::<eframe::web_sys::Response>() else {
            return;
        };

        if !response.ok() {
            return;
        }

        let Ok(array_buffer_promise) = response.array_buffer() else {
            return;
        };

        let Ok(array_buffer) = wasm_bindgen_futures::JsFuture::from(array_buffer_promise).await
        else {
            return;
        };

        let bytes = js_sys::Uint8Array::new(&array_buffer).to_vec();
        ctx.set_fonts(build_font_definitions(Some(bytes)));
    });
}

//! UI component types for mod developers.
//!
//! Mods spawn entities with these components to declare a tab and
//! populate it with UI widgets.  The host reads these entities each
//! frame and translates them into egui controls.  Interaction results
//! are written back to the component fields (e.g. `Button.clicked`),
//! which the mod reads next frame via `query_mut!`.

use bevy_moder_sdk::component;

/// Declares that this mod wants a tab in the main UI.
#[component]
pub struct ModTab {
    pub tab_id: String,
    pub title: String,
}

// Note: manual serde derives must use ::bevy_moder_sdk::serde (not workspace serde)
// because #[component] internally uses bevy_moder_sdk's re-exported serde_core.
#[derive(::bevy_moder_sdk::serde::Serialize, ::bevy_moder_sdk::serde::Deserialize)]
#[serde(crate = "::bevy_moder_sdk::serde")]
pub enum ContainerLayout {
    Column,
    Row,
    ScrollArea,
}

/// A layout container (column, row, scroll area).
#[component]
pub struct Container {
    pub node_id: String,
    pub tab_id: String,
    pub parent_node_id: Option<String>,
    pub layout: ContainerLayout,
}

/// Static label.
#[component]
pub struct Label {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
}

/// Clickable button.  The host sets `clicked = true` when the user
/// presses it; the mod reads and resets it.
#[component]
pub struct Button {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub clicked: bool,
}

/// Checkbox.  The host updates `checked` when the user toggles it.
#[component]
pub struct Checkbox {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub checked: bool,
}

/// Single-line text input.
#[component]
pub struct TextEdit {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub hint: String,
}

/// Collapsible section header.
#[component]
pub struct CollapsingHeader {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub open: bool,
}

/// Separator / divider line.
#[component]
pub struct Separator {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
}

/// Slider for a numeric value.
#[component]
pub struct Slider {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub min: f64,
    pub max: f64,
    pub value: f64,
}

//! WASM mod management for Paiagram.
//!
//! Discovers `.wasm` files in the `mods/` directory next to the executable
//! and exchanges mod actions (load / unload) between the Settings UI and
//! the Bevy schedule via [`ModActionQueue`] + an exclusive system.

use bevy::prelude::*;
use std::collections::HashMap;

/// A single discovered WASM mod on disk.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone, Debug)]
pub struct ModEntry {
    /// Full filesystem path to the `.wasm` file.
    pub path: String,
}

/// Resource tracking all discovered WASM mod files.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Resource, Default)]
pub struct AvailableMods {
    pub mods: Vec<ModEntry>,
}

/// path to actual mod name mapping, updated when a mod is loaded.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Resource, Default)]
pub struct ModNameRegistry {
    pub path_to_name: HashMap<String, String>,
}

/// Actions queued from the Settings UI.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Resource, Default)]
pub struct ModActionQueue {
    items: Vec<ModAction>,
}

#[cfg(not(target_arch = "wasm32"))]
pub enum ModAction {
    Load(String),
    Unload(String),
}

#[cfg(not(target_arch = "wasm32"))]
impl ModActionQueue {
    pub fn push(&mut self, action: ModAction) {
        self.items.push(action);
    }
}

/// Integrates WASM mod support into Paiagram.
///
/// On native targets adds `bevy_moder_runtime::WasmModPlugin`, the
/// [`AvailableMods`] / [`ModActionQueue`] / [`ModNameRegistry`] resources,
/// a startup system that scans the `mods/` directory, and an exclusive
/// system that processes queued load/unload actions.
///
/// On WASM targets the plugin is a no-op.
pub struct PaiagramModsPlugin;

impl Plugin for PaiagramModsPlugin {
    #[cfg(not(target_arch = "wasm32"))]
    fn build(&self, app: &mut App) {
        app.add_plugins(bevy_moder_runtime::WasmModPlugin::default());
        app.init_resource::<AvailableMods>();
        app.init_resource::<ModActionQueue>();
        app.init_resource::<ModNameRegistry>();
        app.add_systems(Startup, scan_mods_directory);
        app.add_systems(Update, process_mod_actions);
    }

    #[cfg(target_arch = "wasm32")]
    fn build(&self, _app: &mut App) {}
}

#[cfg(not(target_arch = "wasm32"))]
fn scan_mods_directory(mut available: ResMut<AvailableMods>) {
    fn mods_directory() -> Option<std::path::PathBuf> {
        if let Ok(exe) = std::env::current_exe() {
            if let Some(parent) = exe.parent() {
                let d = parent.join("mods");
                if d.is_dir() {
                    return Some(d);
                }
            }
        }
        let d = std::path::PathBuf::from("mods");
        if d.is_dir() {
            return Some(d);
        }
        None
    }

    let Some(dir) = mods_directory() else {
        return;
    };

    let mut mods = Vec::new();
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().is_some_and(|e| e == "wasm") {
                mods.push(ModEntry {
                    path: path.to_string_lossy().to_string(),
                });
            }
        }
    }
    mods.sort_by(|a, b| a.path.cmp(&b.path));
    available.mods = mods;
}

#[cfg(not(target_arch = "wasm32"))]
fn process_mod_actions(world: &mut World) {
    let items = {
        let mut q = world.resource_mut::<ModActionQueue>();
        std::mem::take(&mut q.items)
    };
    if items.is_empty() {
        return;
    }

    let mut unloads = Vec::new();
    let mut loads = Vec::new();
    for a in items {
        match a {
            ModAction::Load(p) => loads.push(p),
            ModAction::Unload(name) => unloads.push(name),
        }
    }

    // Unload mods
    for name in &unloads {
        if let Err(e) = bevy_moder_runtime::unload_single_mod(world, name) {
            bevy::log::error!("Failed to unload mod '{}': {}", name, e);
        } else {
            bevy::log::info!("Unloaded mod '{}'", name);
        }
    }
    {
        let mut registry = world.resource_mut::<ModNameRegistry>();
        registry.path_to_name.retain(|_, v| !unloads.contains(v));
    }

    // Load mods
    for path in &loads {
        match bevy_moder_runtime::ModLoader::load_sync(world, path) {
            Ok(name) => {
                bevy::log::info!("Loaded mod '{}' from {}", name, path);
                let mut registry = world.resource_mut::<ModNameRegistry>();
                registry.path_to_name.insert(path.clone(), name);
            }
            Err(e) => {
                bevy::log::error!("Failed to load mod '{}': {}", path, e);
            }
        }
    }
}

