#[derive(::bevy_moder_sdk::serde::Serialize, ::bevy_moder_sdk::serde::Deserialize)]
#[serde(crate = "::bevy_moder_sdk::serde")]
pub enum ContainerLayout {
    Column,
    Row,
    ScrollArea,
}

