    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub clicked: bool,
}

/// Checkbox.  The host updates `checked` when the user toggles it.
#[component]
pub struct Checkbox {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub checked: bool,
}

