#[component]
pub struct TextEdit {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub hint: String,
}

/// Collapsible section header.
#[component]
pub struct CollapsingHeader {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub open: bool,
}

/// Separator / divider line.
#[component]
pub struct Separator {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
}

/// Slider for a numeric value.
#[component]
pub struct Slider {
    pub tab_id: String,
    pub node_id: String,
    pub parent_node_id: Option<String>,
    pub text: String,
    pub min: f64,
    pub max: f64,
    pub value: f64,
}

