```rust
fn sync_mod_tabs(
    mod_tab_query: Query<(Entity, &mod_ui::ModTab)>,
    mut main_ui: ResMut<MainUiState>,
) {
    // Collect all entities' info
    let desired: Vec<(Entity, String, String)> = mod_tab_query
        .iter()
        .map(|(_entity, t)| {
            (_entity, t.tab_id.clone(), t.title.clone())
        })
        .collect();

    // Which tab_ids are currently desired (for staleness check)
    let desired_tab_ids: HashSet<&str> = desired.iter().map(|(_, id, _)| id.as_str()).collect();

    // Scan tiles: collect stale ones and existing ones
    let mut stale: Vec<(egui_tiles::TileId, String)> = Vec::new();
    let mut existing_tab_ids: HashSet<String> = HashSet::new();

    for (id, tile) in main_ui.tree.tiles.iter() {
        if let egui_tiles::Tile::Pane(MainTab::ModTab(w)) = tile {
            if desired_tab_ids.contains(w.tab_id.as_str()) {
                existing_tab_ids.insert(w.tab_id.clone());
            } else {
                stale.push((*id, w.tab_id.clone()));
            }
        }
    }

    // Remove stale tiles
    for (id, tab_id) in &stale {
        main_ui.tree.tiles.remove(*id);
        main_ui.hidden_mod_tabs.remove(tab_id);
        main_ui.seen_mod_tabs.remove(tab_id);
    }

    // Update titles of existing tiles
    for (_, tile) in main_ui.tree.tiles.iter_mut() {
        if let egui_tiles::Tile::Pane(MainTab::ModTab(w)) = tile {
            if let Some((entity, id, title)) = desired.iter().find(|(_, id, _)| id == &w.tab_id) {
                if w.title != *title {
                    w.title = title.clone();
                }
            }
        }
    }

    // Handle entities without tiles - just create one tile per unseen tab_id
    // (or per entity? For now, one tile per tab_id to avoid duplicates)
    for (entity, tab_id, title) in &desired {
        if existing_tab_ids.contains(tab_id) {
            continue;
        }

        if main_ui.hidden_mod_tabs.contains(tab_id) {
            continue;
        }

        if main_ui.seen_mod_tabs.contains(tab_id) {
            main_ui.hidden_mod_tabs.insert(tab_id.clone());
            continue;
        }

        main_ui.seen_mod_tabs.insert(tab_id.clone());
        main_ui.push_to_focused_leaf(MainTab::ModTab(ModTabWidget {
            tab_id: tab_id.clone(),
            title: title.clone(),
        }));
        existing_tab_ids.insert(tab_id.clone()); // prevent duplicate tiles for same tab_id
    }
}
```

