pub struct Graph {
    /// The actual map
    pub map: DiGraphMap<Entity, Entity, EntityHash>,
}

/// Reconstructs the map when mapping entities
impl MapEntities for Graph {
    fn map_entities<E: EntityMapper>(&mut self, entity_mapper: &mut E) {
        // construct a new graph instead
        let (nodes, edges) = self.capacity();
        let mut new_graph = DiGraphMap::with_capacity(nodes, edges);
        for mut node in self.nodes() {
            node.map_entities(entity_mapper);
            new_graph.add_node(node);
        }
        for (mut source, mut target, weight) in self.all_edges() {
            let mut weight = *weight;
            source.map_entities(entity_mapper);
            target.map_entities(entity_mapper);
            weight.map_entities(entity_mapper);
            new_graph.add_edge(source, target, weight);
        }
        self.map = new_graph;
    }
}

impl Graph {
    /// Find a route between the source stop and the target stop.
    /// Returns [`None`] if no valid route exists.
    /// Returns the total length in i32 and the stations on the route if a valid route is found.
    pub fn route_between(
        &self,
        source: Entity,
        target: Entity,
        interval_q: &Query<IntervalQuery>,
    ) -> Option<(i32, Vec<Entity>)> {
        astar(
            &self.map,
            source,
            |f| f == target,
            |e| {
                let Ok(i) = interval_q.get(*e.weight()) else {
                    return i32::MAX;
                };
                i.distance().0
            },
            |_| 0,
        )
    }
    /// Find a route given a set of stations that must be on the route.
    /// Returns [`None`] if no valid route exists.
    /// Returns the total length in i32 and the stations on the route if a valid route is found.
    pub fn route_between_source_waypoint_target(
        &self,
        mut points: impl Iterator<Item = Entity>,
        interval_q: &Query<IntervalQuery>,
    ) -> Option<(i32, Vec<Entity>)> {
        let mut prev = points.next()?;
        let mut total_length = 0;
        let mut passes = vec![prev];
        for curr in points {
            let (leg_length, leg_points) = astar(
                &self.map,
                prev,
                |f| f == curr,
                |e| {
                    let Ok(i) = interval_q.get(*e.weight()) else {
                        return i32::MAX;
                    };
                    i.distance().0
                },
                |_| 0,
            )?;
            total_length += leg_length;
            passes.extend_from_slice(&leg_points[1..]);
            prev = curr;
        }
        Some((total_length, passes))
    }

    /// Transforms the graph into a normal [`petgraph::Graph`], which could be useful for mapping to
    /// e.g. graphviz graphs.
    pub fn into_graph(self) -> petgraph::Graph<Entity, Entity> {
        self.map.into_graph()
    }
}

