//! Example host application demonstrating dynamic mod loading and unloading.
//!
//! Uses MinimalPlugins to run for a fixed number of frames.
//! Sequence:
//!   1. Load mod at startup
//!   2. Run 2 frames (mod's Update systems run)
//!   3. Unload mod
//!   4. Run 2 frames (mod's Update systems are gone)
//!   5. Reload mod
//!   6. Run 2 frames (mod's Update systems run again)
//!   7. Exit

use bevy::{ecs::message::MessageWriter, log::LogPlugin, prelude::*};
use bevy_moder_runtime::{
    ModLoader, ModUnloader, WasmModPlugin,
    register_component, register_resource, register_message,
};

#[register_component]
#[derive(Component, Debug)]
pub struct Square(pub Vec2);

#[register_component]
#[derive(Component, Debug)]
pub struct Rect(pub IVec2);

#[register_resource]
#[derive(Resource, Debug)]
pub struct Player(pub Vec2);

#[register_message]
pub struct HostGreeting(pub String);

#[register_message]
pub struct ModReply(pub String);

/// Tracks the demo sequence state.
#[derive(Resource)]
struct DemoSequence {
    /// Incremented each Update.
    frame: u32,
    mod_path: String,
}

fn load_mod_at_startup(world: &mut World) {
    let path = world.resource::<DemoSequence>().mod_path.clone();
    info!("[demo] Step 1 – Loading mod at startup");
    match ModLoader::load_sync(world, path) {
        Ok(name) => info!("  → loaded '{name}'"),
        Err(e) => error!("Failed to load mod: {e}"),
    }
}

fn send_greeting_system(mut writer: MessageWriter<HostGreeting>) {
    writer.write(HostGreeting("Hello from the Bevy host!".into()));
}

fn read_mod_replies(mut reader: bevy::ecs::message::MessageReader<ModReply>) {
    for ModReply(msg) in reader.read() {
        info!("[host] Mod replied: '{}'", msg);
    }
}

fn spawn_example_data(mut commands: Commands) {
    commands.spawn((Square(Vec2::new(0.0, 1.0)), Rect(IVec2::new(3, 4))));
    commands.spawn((Square(Vec2::new(2.0, 3.6)), Rect(IVec2::new(32, 48))));
    commands.insert_resource(Player(Vec2::new(10.0, 20.0)));
}

/// Advance the demo sequence.
///
/// frame 1-2: mod loaded, Update runs
///   frame 2: queue unload
/// frame 3: mod unloaded, no Update systems
/// frame 4-5: mod reloaded (via load_sync in PreUpdate), runs again
///   frame 6: exit
fn demo_sequencer(
    mut seq: ResMut<DemoSequence>,
    mut unloader: ResMut<ModUnloader>,
) {
    seq.frame += 1;
    info!("[demo] === Frame {} ===", seq.frame);

    match seq.frame {
        2 => {
            info!("[demo] Step 3 – Unloading mod");
            unloader.unload("hello_world_mod");
        }
        6 => {
            info!("[demo] Step 7 – Done, exiting");
            std::process::exit(0);
        }
        _ => {}
    }
}

fn reload_mod(world: &mut World) {
    let frame = world.resource::<DemoSequence>().frame;
    if frame != 3 {
        return;
    }
    let path = world.resource::<DemoSequence>().mod_path.clone();
    info!("[demo] Step 5 – Reloading mod");
    match ModLoader::load_sync(world, path) {
        Ok(name) => info!("  → reloaded '{name}'"),
        Err(e) => error!("Failed to reload mod: {e}"),
    }
}

fn main() {
    let mod_path = env!("CARGO_MANIFEST_DIR").to_owned()
        + "/../../../target/wasm32-wasip1/debug/game_mod.wasm";

    App::new()
        .add_plugins(LogPlugin::default())
        .add_plugins(MinimalPlugins)
        .add_plugins(WasmModPlugin::default())
        .insert_resource(DemoSequence {
            frame: 0,
            mod_path,
        })
        .add_message::<HostGreeting>()
        .add_message::<ModReply>()
        .add_systems(Startup, (spawn_example_data, load_mod_at_startup))
        .add_systems(PreUpdate, (read_mod_replies, reload_mod))
        .add_systems(Update, (
            send_greeting_system,
            demo_sequencer,
        ))
        .run();
}

