use crate::ModState;
use bevy::log::*;
use bevy::prelude::*;
use std::any::Any;
use std::collections::HashMap;
use std::sync::Mutex;

#[derive(Clone)]
pub struct MessageRegistration {
    pub type_name: &'static str,
    pub serialize_fn: fn(&(dyn Any + Send + Sync)) -> Vec<u8>,
    pub deserialize_fn: fn(&[u8]) -> Box<dyn Any + Send + Sync>,
    pub write_fn: fn(&mut World, Vec<u8>),
    pub drain_fn: fn(&mut World) -> Vec<u8>,
}

static MESSAGE_REGS: Mutex<Vec<MessageRegistration>> = Mutex::new(Vec::new());

pub fn register_message(reg: MessageRegistration) {
    MESSAGE_REGS.lock().unwrap().push(reg);
}

pub fn find_message_registration(name: &str) -> Option<MessageRegistration> {
    MESSAGE_REGS
        .lock()
        .unwrap()
        .iter()
        .find(|r| r.type_name == name)
        .cloned()
}

pub fn iter_messages() -> Vec<MessageRegistration> {
    MESSAGE_REGS.lock().unwrap().clone()
}

#[derive(Resource, Default)]
pub struct MessageBuffer {
    /// type_name → bincode-encoded `Vec<M>` (for mod consumption)
    pub pending: HashMap<String, Vec<u8>>,
    /// type_name → serialised messages (mod → host)
    pub outgoing: HashMap<String, Vec<Vec<u8>>>,
}

/// Drain all registered `Messages<M>` resources into `MessageBuffer.pending`.
///
/// Runs **after** the host's message-writing systems (in PostUpdate)
/// so that messages written by host systems this frame are immediately
/// available to the mod.
pub fn buffer_messages_for_mod(world: &mut World) {
    let mut entries: Vec<(String, Vec<u8>)> = Vec::new();
    for reg in iter_messages() {
        let blob = (reg.drain_fn)(world);
        if !blob.is_empty() {
            entries.push((reg.type_name.to_string(), blob));
        }
    }

    let mut buffer = world.resource_mut::<MessageBuffer>();
    buffer.pending.clear();
    buffer.outgoing.clear();
    for (name, blob) in entries {
        buffer.pending.insert(name, blob);
    }
}

/// Write all outgoing messages from `MessageBuffer.outgoing` into the
/// respective `Messages<M>` resources.
pub fn flush_messages_from_mod(world: &mut World) {
    let outgoing = {
        let mut buffer = world.resource_mut::<MessageBuffer>();
        std::mem::take(&mut buffer.outgoing)
    };

    for (type_name, serialized_messages) in &outgoing {
        let reg = match find_message_registration(type_name) {
            Some(r) => r,
            None => {
                error!(
                    "flush_messages: no registration for '{}', dropping {} message(s)",
                    type_name,
                    serialized_messages.len(),
                );
                continue;
            }
        };
        for data in serialized_messages {
            (reg.write_fn)(world, data.clone());
        }
    }
}

/// Host system — prints outgoing messages (type_name + count) for debugging.
/// Register this with `app.add_systems(PreUpdate, message::log_outgoing_messages)`
/// if you want to see what the mod sent before the host's own handlers run.
pub fn log_outgoing_messages(buffer: Res<MessageBuffer>) {
    for (type_name, msgs) in &buffer.outgoing {
        info!(
            "[host] {} outgoing message(s) of type '{}'",
            msgs.len(),
            type_name
        );
    }
}

pub fn host_handle_read_messages(
    mut caller: wasmtime::Caller<'_, ModState>,
    name_ptr: i32,
    name_len: i32,
    output: i32,
    out_len: i32,
) -> i32 {
    let memory = match caller.get_export("memory") {
        Some(e) => e.into_memory().unwrap(),
        None => return 1,
    };

    let mut name_buf = vec![0u8; name_len as usize];
    if memory
        .read(&caller, name_ptr as usize, &mut name_buf)
        .is_err()
    {
        error!("read_messages: failed to read type name");
        return 1;
    }
    let type_name = match String::from_utf8(name_buf) {
        Ok(s) => s,
        Err(_) => return 1,
    };

    let world = match caller.data().get_world() {
        Some(w) => w,
        None => return 1,
    };

    let payload = {
        unsafe {
            let world_mut = world.world_mut();
            let buffer = match world_mut.get_resource::<MessageBuffer>() {
                Some(b) => b,
                None => return 1,
            };
            match buffer.pending.get(&type_name) {
                Some(blob) => blob.clone(),
                None => return 1,
            }
        }
    };

    if output == 0 {
        let len: i32 = payload.len() as i32;
        let len_bytes = i32::to_le_bytes(len);
        if memory
            .write(&mut caller, out_len as usize, &len_bytes)
            .is_err()
        {
            error!("read_messages: failed to write size");
            return 1;
        }
        len
    } else {
        if memory
            .write(&mut caller, output as usize, &payload)
            .is_err()
        {
            error!("read_messages: failed to write output");
            return 1;
        }
        let len_bytes = i32::to_le_bytes(payload.len() as i32);
        if memory
            .write(&mut caller, out_len as usize, &len_bytes)
            .is_err()
        {
            error!("read_messages: failed to write size");
            return 1;
        }
        0
    }
}

pub fn host_handle_write_message(
    mut caller: wasmtime::Caller<'_, ModState>,
    name_ptr: i32,
    name_len: i32,
    data_ptr: i32,
    data_len: i32,
) {
    let memory = match caller.get_export("memory") {
        Some(e) => e.into_memory().unwrap(),
        None => return,
    };

    let mut name_buf = vec![0u8; name_len as usize];
    if memory
        .read(&caller, name_ptr as usize, &mut name_buf)
        .is_err()
    {
        error!("write_message: failed to read type name");
        return;
    }
    let type_name = match String::from_utf8(name_buf) {
        Ok(s) => s,
        Err(_) => return,
    };

    let mut data_buf = vec![0u8; data_len as usize];
    if memory
        .read(&caller, data_ptr as usize, &mut data_buf)
        .is_err()
    {
        error!("write_message: failed to read data");
        return;
    }

    let world = match caller.data().get_world() {
        Some(w) => w,
        None => return,
    };

    unsafe {
        let world_mut = world.world_mut();
        let mut buffer = match world_mut.get_resource_mut::<MessageBuffer>() {
            Some(b) => b,
            None => {
                error!("write_message: MessageBuffer not found");
                return;
            }
        };
        buffer
            .outgoing
            .entry(type_name)
            .or_default()
            .push(data_buf);
    }
}

extern crate proc_macro;

use proc_macro::TokenStream;
use quote::quote;
use syn::{parse_macro_input, DeriveInput};

/// Register a Bevy **component** that mods can query / spawn.
///
/// The struct name becomes the component ID.
///
/// # Example
/// ```ignore
/// #[register_component]
/// #[derive(Component, Debug)]
/// pub struct Square(pub Vec2);
/// // id = "Square"
/// ```
#[proc_macro_attribute]
pub fn register_component(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);
    let struct_name = &derive_input.ident;
    let component_id = struct_name.to_string();

    let ctor_name = quote::format_ident!("__mod_ctor_comp_{}", struct_name);

    let expanded = quote! {
        #[derive(::bevy_moder_runtime::serde::Serialize, ::bevy_moder_runtime::serde::Deserialize)]
        #[serde(crate = "::bevy_moder_runtime::serde")]
        #[derive(bevy::prelude::Reflect)]
        #derive_input

        #[allow(non_snake_case)]
        #[::bevy_moder_runtime::ctor::ctor]
        fn #ctor_name() {
            bevy_moder_runtime::component::register_component(
                #component_id,
                (|component: bevy::ptr::Ptr<'_>| -> Vec<u8> {
                    unsafe {
                        let c = component.deref::<#struct_name>();
                        ::bevy_moder_runtime::bincode::serde::encode_to_vec(c, ::bevy_moder_runtime::bincode::config::standard())
                            .unwrap_or_default()
                    }
                }) as fn(bevy::ptr::Ptr<'_>) -> Vec<u8>,
                (|data: &[u8]| -> Box<dyn std::any::Any> {
                    let (v, _) = ::bevy_moder_runtime::bincode::serde::decode_from_slice::<#struct_name, _>(
                        data, ::bevy_moder_runtime::bincode::config::standard(),
                    ).expect("failed to deserialise mod_component");
                    Box::new(v)
                }) as fn(&[u8]) -> Box<dyn std::any::Any>,
                (|| -> std::any::TypeId {
                    std::any::TypeId::of::<#struct_name>()
                }) as fn() -> std::any::TypeId,
                (|registry: &mut bevy::reflect::TypeRegistry| {
                    registry.register::<#struct_name>();
                }) as fn(&mut bevy::reflect::TypeRegistry),
                (|entity: &mut bevy::ecs::world::EntityWorldMut,
                  component: Box<dyn std::any::Any>| {
                    if let Ok(c) = component.downcast::<#struct_name>() {
                        entity.insert(*c);
                    }
                }) as fn(&mut bevy::ecs::world::EntityWorldMut, Box<dyn std::any::Any>),
            );
        }
    };

    TokenStream::from(expanded)
}

/// Register a Bevy **resource** that mods can read.
///
/// The struct name becomes the resource ID.
///
/// # Example
/// ```ignore
/// #[register_resource]
/// #[derive(Resource, Debug)]
/// pub struct Player(pub Vec2);
/// // id = "Player"
/// ```
#[proc_macro_attribute]
pub fn register_resource(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);
    let struct_name = &derive_input.ident;
    let resource_id = struct_name.to_string();

    let ctor_name = quote::format_ident!("__mod_ctor_res_{}", struct_name);

    let expanded = quote! {
        #[derive(::bevy_moder_runtime::serde::Serialize, ::bevy_moder_runtime::serde::Deserialize)]
        #[serde(crate = "::bevy_moder_runtime::serde")]
        #[derive(bevy::prelude::Reflect)]
        #derive_input

        #[allow(non_snake_case)]
        #[::bevy_moder_runtime::ctor::ctor]
        fn #ctor_name() {
            bevy_moder_runtime::resource::register_resource(
                #resource_id,
                (|resource: bevy::ptr::Ptr<'_>| -> Vec<u8> {
                    unsafe {
                        let r = resource.deref::<#struct_name>();
                        ::bevy_moder_runtime::bincode::serde::encode_to_vec(r, ::bevy_moder_runtime::bincode::config::standard())
                            .unwrap_or_default()
                    }
                }) as fn(bevy::ptr::Ptr<'_>) -> Vec<u8>,
                (|data: &[u8]| -> Box<dyn std::any::Any> {
                    let (v, _) = ::bevy_moder_runtime::bincode::serde::decode_from_slice::<#struct_name, _>(
                        data, ::bevy_moder_runtime::bincode::config::standard(),
                    ).expect("failed to deserialise mod_resource");
                    Box::new(v)
                }) as fn(&[u8]) -> Box<dyn std::any::Any>,
                (|| -> std::any::TypeId {
                    std::any::TypeId::of::<#struct_name>()
                }) as fn() -> std::any::TypeId,
                (|registry: &mut bevy::reflect::TypeRegistry| {
                    registry.register::<#struct_name>();
                }) as fn(&mut bevy::reflect::TypeRegistry),
                (|world: &mut bevy::prelude::World, component: Box<dyn std::any::Any>| {
                    if let Ok(c) = component.downcast::<#struct_name>() {
                        world.insert_resource(*c);
                    }
                }) as fn(&mut bevy::prelude::World, Box<dyn std::any::Any>),
            );
        }
    };

    TokenStream::from(expanded)
}

#[proc_macro_attribute]
pub fn register_message(_args: TokenStream, input: TokenStream) -> TokenStream {
    let derive_input = parse_macro_input!(input as DeriveInput);
    let struct_name = &derive_input.ident;
    let type_name = struct_name.to_string();

    let ctor_name = quote::format_ident!("__mod_ctor_msg_{}", struct_name);

    let expanded = quote! {
        #[derive(::bevy_moder_runtime::serde::Serialize, ::bevy_moder_runtime::serde::Deserialize)]
        #[serde(crate = "::bevy_moder_runtime::serde")]
        #derive_input
        impl bevy::ecs::message::Message for #struct_name {}

        #[allow(non_snake_case)]
        #[::bevy_moder_runtime::ctor::ctor]
        fn #ctor_name() {
            bevy_moder_runtime::message::register_message(
                bevy_moder_runtime::message::MessageRegistration {
                    type_name: #type_name,
                    serialize_fn: (|v: &(dyn std::any::Any + Send + Sync)| -> Vec<u8> {
                        let msg = v.downcast_ref::<#struct_name>().expect("register_message serialise");
                        ::bevy_moder_runtime::bincode::serde::encode_to_vec(msg, ::bevy_moder_runtime::bincode::config::standard())
                            .unwrap_or_default()
                    }) as fn(&(dyn std::any::Any + Send + Sync)) -> Vec<u8>,
                    deserialize_fn: (|data: &[u8]| -> Box<dyn std::any::Any + Send + Sync> {
                        let (v, _) = ::bevy_moder_runtime::bincode::serde::decode_from_slice::<#struct_name, _>(
                            data, ::bevy_moder_runtime::bincode::config::standard(),
                        ).expect("failed to deserialise message");
                        Box::new(v)
                    }) as fn(&[u8]) -> Box<dyn std::any::Any + Send + Sync>,
                    write_fn: (|world: &mut bevy::prelude::World, data: Vec<u8>| {
                        let (msg, _): (#struct_name, _) =
                            ::bevy_moder_runtime::bincode::serde::decode_from_slice(&data, ::bevy_moder_runtime::bincode::config::standard())
                                .expect("write_fn deserialise");
                        world.init_resource::<bevy::ecs::message::Messages<#struct_name>>();
                        world.resource_mut::<bevy::ecs::message::Messages<#struct_name>>()
                            .write(msg);
                    }) as fn(&mut bevy::prelude::World, Vec<u8>),
                    drain_fn: (|world: &mut bevy::prelude::World| -> Vec<u8> {
                        let msgs: Vec<#struct_name> =
                            match world.get_resource_mut::<bevy::ecs::message::Messages<#struct_name>>()
                            {
                                Some(mut m) => m.drain().collect(),
                                None => return vec![],
                            };
                        ::bevy_moder_runtime::bincode::serde::encode_to_vec(&msgs, ::bevy_moder_runtime::bincode::config::standard())
                            .unwrap_or_default()
                    }) as fn(&mut bevy::prelude::World) -> Vec<u8>,
                },
            );
        }
    };

    TokenStream::from(expanded)
}

