/// System registry — populated at WASM init by `#[ctor]` functions generated
/// from each `#[system]`.  The static buffers avoid heap allocation during
/// the constructor phase (before the Rust allocator is ready).

const MAX_SYSTEMS: usize = 1024;

#[derive(Copy, Clone)]
#[repr(C)]
struct RawSysEntry {
    name_ptr: *const u8,
    name_len: usize,
    schedule: u8,
}

static mut SYS_COUNT: usize = 0;
static mut SYS_ENTRIES: [RawSysEntry; MAX_SYSTEMS] =
    [RawSysEntry { name_ptr: core::ptr::null(), name_len: 0, schedule: 0 }; MAX_SYSTEMS];

/// Register a system (called from `#[ctor]`-generated code during module init).
pub fn register_system(name: &'static str, schedule: u8) {
    unsafe {
        let idx = SYS_COUNT;
        if idx < MAX_SYSTEMS {
            SYS_ENTRIES[idx] = RawSysEntry {
                name_ptr: name.as_ptr(),
                name_len: name.len(),
                schedule,
            };
            SYS_COUNT = idx + 1;
        }
    }
}

/// Return the number of registered systems.
pub fn system_count() -> usize {
    unsafe { SYS_COUNT }
}

/// Return pointer/length pairs for all registered system names.
pub fn system_name_entries() -> &'static [(u32, u32)] {
    use std::sync::OnceLock;
    static CACHE: OnceLock<Vec<(u32, u32)>> = OnceLock::new();
    CACHE.get_or_init(|| {
        unsafe {
            let count = SYS_COUNT;
            let mut v = Vec::with_capacity(count);
            for i in 0..count {
                let e = &SYS_ENTRIES[i];
                v.push((e.name_ptr as u32, e.name_len as u32));
            }
            v
        }
    })
}

// Mod name (set by `mod_def!` at module init)

use std::sync::OnceLock;

static MOD_NAME: OnceLock<String> = OnceLock::new();

/// Set the mod name (called from `mod_def!` ctor).
pub fn set_mod_name(name: &str) {
    MOD_NAME.get_or_init(|| name.to_string());
}

/// Get the current mod name.
