//
// ResMutGuard
//

/// Guard for `res_mut!` — provides mutable access to a resource
/// and automatically writes back to the host on drop.
pub struct ResMutGuard<T: serde::Serialize> {
    pub value: Option<T>,
    dirty: bool,
    resource_id: &'static str,
}

impl<T: serde::Serialize> Drop for ResMutGuard<T> {
    fn drop(&mut self) {
        if !self.dirty {
            return;
        }
        if let Some(ref value) = self.value {
            if let Ok(data) =
                bincode::serde::encode_to_vec(value, bincode::config::standard())
            {
                // Resource ID must be bincode-encoded (the host expects a String).
                if let Ok(id_encoded) = bincode::serde::encode_to_vec(
                    self.resource_id,
                    bincode::config::standard(),
                ) {
                    unsafe {
                        __mod_set_resource(
                            id_encoded.as_ptr(),
                            id_encoded.len(),
                            data.as_ptr(),
                            data.len(),
                        );
                    }
                }
            }
        }
    }
}

impl<T: serde::Serialize> ResMutGuard<T> {
    pub fn new(value: Option<T>, resource_id: &'static str) -> Self {
        ResMutGuard {
            value,
            dirty: false,
            resource_id,
        }
    }

    /// Get a mutable reference to the inner value if present.
    /// Sets the dirty flag so the value is written back on drop.
    pub fn as_mut(&mut self) -> Option<&mut T> {
        if self.value.is_some() {
            self.dirty = true;
        }
        self.value.as_mut()
    }

    /// Get an immutable reference to the inner value.
    pub fn as_ref(&self) -> Option<&T> {
        self.value.as_ref()
    }

    /// Get a mutable reference, initialising with `f` if the value is absent.
    ///
    /// This is the recommended way to initialise a mod-defined resource:
    ///
    /// ```ignore
    /// let mut guard = res_mut!(GameState);
    /// let gs = guard.or_insert_with(|| GameState { score: 0, level: 0 });
    /// gs.score += 10;
    /// ```
    pub fn or_insert_with(&mut self, f: impl FnOnce() -> T) -> &mut T {
        self.dirty = true;
        self.value.get_or_insert_with(f)
    }
}

/// Guard for `query_mut!` — provides mutable iteration over entities
/// and automatically writes back modified components to the host on drop.
///
/// Modify components via `iter_mut()`; the guard writes back only
/// when `iter_mut()` has been called at least once.
///
/// T must be a tuple type that implements `ComponentFlatten` and `Serialize`.
pub struct QueryMutGuard<T: serde::Serialize + ComponentFlatten> {
    items: Vec<T>,
    entity_ids: Vec<u64>,
    component_ids: Vec<&'static str>,
    dirty: bool,
}

impl<T: serde::Serialize + ComponentFlatten> Drop for QueryMutGuard<T> {
    fn drop(&mut self) {
        if !self.dirty {
            return;
        }

        let entities: Vec<(u64, Vec<Vec<u8>>)> = self
            .items
            .iter()
            .zip(self.entity_ids.iter())
            .map(|(item, &eid)| (eid, item.flatten_components()))
            .collect();

        if let Ok(ids_payload) = bincode::serde::encode_to_vec(
            &self.component_ids,
            bincode::config::standard(),
        ) {
            if let Ok(entities_payload) = bincode::serde::encode_to_vec(
                &entities,
                bincode::config::standard(),
            ) {
                unsafe {
                    __mod_update_components(
                        ids_payload.as_ptr(),
                        ids_payload.len(),
                        entities_payload.as_ptr(),
                        entities_payload.len(),
                    );
                }
            }
        }
    }
}

impl<T: serde::Serialize + ComponentFlatten> QueryMutGuard<T> {
    pub fn new(
        items: Vec<T>,
        entity_ids: Vec<u64>,
        component_ids: Vec<&'static str>,
    ) -> Self {
        QueryMutGuard {
            items,
            entity_ids,
            component_ids,
            dirty: false,
        }
    }

    /// Iterate over mutable references to each entity's component tuple.
    /// Sets the dirty flag so changes are written back on drop.
    pub fn iter_mut(&mut self) -> std::slice::IterMut<'_, T> {
        self.dirty = true;
        self.items.iter_mut()
    }

    /// Iterate over immutable references to each entity's component tuple.
    pub fn iter(&self) -> std::slice::Iter<'_, T> {
        self.items.iter()
    }

    /// Returns the number of entities captured by this guard.
    pub fn len(&self) -> usize {
        self.items.len()
    }

    /// Returns true if no entities were captured.
    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

// FFI declarations – host functions imported by the WASM module
unsafe extern "C" {
    pub fn __mod_log(ptr: *const u8, len: usize, level: u8);

    pub fn __mod_query_components(
        component_ids_ptr: *const u8,
        component_ids_len: usize,
        result_ptr: *mut u8,
    ) -> usize;

    pub fn __mod_query_resources(
        resource_id_ptr: *const u8,
        resource_id_len: usize,
        result_ptr: *mut u8,
    ) -> usize;

    pub fn __mod_spawn_entities(components_ptr: *const u8, components_len: usize);

    pub fn __mod_free_memory(ptr: *mut u8, len: usize);

    pub fn __mod_get_name() -> *const u8;

    pub fn __mod_set_resource(
        resource_id_ptr: *const u8,
        resource_id_len: usize,
        data_ptr: *const u8,
        data_len: usize,
    );

    pub fn __mod_update_components(
        component_ids_ptr: *const u8,
        component_ids_len: usize,
        entities_ptr: *const u8,
        entities_len: usize,
    );

    pub fn __mod_read_messages(
        name_ptr: *const u8,
        name_len: i32,
        output: *mut u8,
        out_len: *mut i32,
    ) -> i32;

    pub fn __mod_write_message(
        name_ptr: *const u8,
        name_len: i32,
        data_ptr: *const u8,
        data_len: i32,
    );
}

/// Read all pending messages of a given type.
///
/// Returns a `Vec<MsgType>` (empty if none).  On error logs the
/// problem and returns an empty vec (never panics).
#[macro_export]
macro_rules! message {
    ($msg_type:ty) => {{
        let result: Vec<$msg_type> = 'msg: {
            let type_name = stringify!($msg_type);
            let name_bytes = type_name.as_bytes();

            let mut buf_len: i32 = 0;
            let ret = unsafe {
                $crate::__mod_read_messages(
                    name_bytes.as_ptr(),
                    name_bytes.len() as i32,
                    core::ptr::null_mut(),
                    &mut buf_len as *mut i32,
                )
            };

            if ret <= 0 || buf_len <= 0 {
                break 'msg Vec::new();
            }

            let mut buf = vec![0u8; buf_len as usize];
            unsafe {
                $crate::__mod_read_messages(
                    name_bytes.as_ptr(),
                    name_bytes.len() as i32,
                    buf.as_mut_ptr(),
                    &mut buf_len,
                );
            }

            // The payload is bincode-encoded Vec<Vec<u8>> (one inner Vec per message),
            // but for the WASM side we decode directly as Vec<$msg_type> because the
            // buffer contains the raw bytes of the serialized messages.
            match bincode::serde::decode_from_slice::<Vec<$msg_type>, _>(
                &buf, bincode::config::standard(),
            ) {
                Ok((msgs, _)) => msgs,
                Err(e) => {
                    $crate::log_error!(
                        "message! decode {} failed: {}",
                        stringify!($msg_type), e,
                    );
                    break 'msg Vec::new();
                }
            }
        };

        result
    }};
}

/// Send a message to the host.
///
/// On error logs the problem (never panics).
#[macro_export]
macro_rules! send_message {
    ($msg_type:ty, $msg:expr) => {{
        'send: {
            let type_name = stringify!($msg_type);
            match bincode::serde::encode_to_vec(&$msg, bincode::config::standard()) {
                Ok(data) => unsafe {
                    $crate::__mod_write_message(
                        type_name.as_ptr(),
                        type_name.len() as i32,
                        data.as_ptr(),
                        data.len() as i32,
                    );
                },
                Err(e) => {
                    $crate::log_error!(
                        "send_message! encode {} failed: {}",
                        stringify!($msg_type), e,
                    );
                }
            }
        }
    }};

    // Shorthand for struct-style messages: send_message!(MsgType { field: val })
    ($msg_type:ty { $($field:ident: $val:expr),+ $(,)? }) => {
        send_message!($msg_type, $msg_type { $($field: $val),+ })
    };
}

