//! Host-side entity spawn handler.

use crate::component::find_component_registration;
use crate::mod_types;
use crate::ModState;
use bevy::log::*;

/// Host function: `__mod_spawn_entities`
pub fn host_handle_spawn_entities(
    mut caller: wasmtime::Caller<'_, ModState>,
    components_ptr: i32,
    components_len: i32,
) {
    let memory = match caller.get_export("memory") {
        Some(e) => e.into_memory().unwrap(),
        None => {
            error!("spawn: no memory export");
            return;
        }
    };

    let data = memory.data(&caller);
    let bytes = &data[components_ptr as usize..(components_ptr + components_len) as usize];

    let components_data: Vec<(String, Vec<u8>)> =
        match bincode::serde::decode_from_slice(bytes, bincode::config::standard()) {
            Ok((d, _)) => d,
            Err(e) => {
                error!("spawn: deserialise failed: {}", e);
                return;
            }
        };

    let world = match caller.data().get_world() {
        Some(w) => w,
        None => return,
    };

    spawn_entity_with_components(&world, &components_data);
}

fn spawn_entity_with_components(
    world: &bevy::ecs::world::unsafe_world_cell::UnsafeWorldCell<'_>,
    components_data: &[(String, Vec<u8>)],
) {
    unsafe {
        let world_mut = world.world_mut();
        let mut entity = world_mut.spawn_empty();

        let mut native_components = Vec::new();
        let mut mod_components = Vec::new();

        for (cid, comp_data) in components_data {
            if let Some(reg) = find_component_registration(cid) {
                let boxed = (reg.deserialize_fn)(comp_data);
                (reg.insert_fn)(&mut entity, boxed);
                native_components.push(cid.clone());
            } else if mod_types::is_mod_component(cid) {
                let type_name = cid.split("::").nth(1).unwrap_or(cid).to_string();
                mod_components.push(mod_types::ModComponentData {
                    type_name,
                    data: comp_data.clone(),
                });
            } else {
                error!("spawn: no registration for '{}'", cid);
            }
        }

        let mod_count = mod_components.len();
        if mod_count > 0 {
            entity.insert(mod_types::ModComponents {
                components: mod_components,
            });
        }

        let id = entity.id();
        if mod_count > 0 {
            info!(
                "Spawned entity {:?} (native={}, mod={})",
                id,
                native_components.len(),
                mod_count,
            );
        } else {
            info!("Spawned entity {:?}", id);
        }
    }
}

