impl std::fmt::Display for NodeCoor {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let lat_dir = if self.lat < 0.0 { 'S' } else { 'N' };
        let lon_dir = if self.lon < 0.0 { 'W' } else { 'E' };
        write!(
            f,
            "{:.4}°{}, {:.4}°{}",
            self.lat.abs(),
            lat_dir,
            self.lon.abs(),
            lon_dir
        )
    }
}

impl Default for NodeCoor {
    fn default() -> Self {
        Self::new(0.0, 0.0)
    }
}

impl NodeCoor {
    pub fn new(lon: f64, lat: f64) -> Self {
        Self { lon, lat }
    }
    pub fn from_xy(x: f64, y: f64) -> Self {
        let (lon, lat) = xy_to_lon_lat(x, y);
        Self::new(lon, lat)
    }
    pub fn to_xy(&self) -> (f64, f64) {
        lon_lat_to_xy(self.lon, self.lat)
    }
    pub fn to_xy_arr(&self) -> [f64; 2] {
        let (x, y) = self.to_xy();
        [x, y]
    }
    /// Shift the node on the canvas by x and y
    pub fn shift(&mut self, dx: f64, dy: f64) {
        self.lon += dx;
        self.lat += dy;
    }
    /// Linearly interpolates between `self` and `other` by fraction `t`.
    /// `t` is typically between 0.0 and 1.0.
    pub fn lerp(&self, other: &Self, t: f64) -> Self {
        let end_lon = other.lon;
        let end_lat = other.lat;

        Self {
            lon: self.lon + (end_lon - self.lon) * t,
            lat: self.lat + (end_lat - self.lat) * t,
        }
    }
}

