//! Station API for mod developers.
//!
//! Binary-compatible with `paiagram_core::station::Station` and
//! `bevy::prelude::Name`.  Spawn these on one entity to create a station.

use bevy_moder_sdk::component;

/// Station marker.  Binary-compatible with `paiagram_core::station::Station`.
///
/// When paired with a [`Node`](crate::graph::Node) (and an optional
/// [`Name`]) on the same entity, the host upgrades it into a full
/// Paiagram station.
#[component]
pub struct Station;

/// Station name.  Binary-compatible with `bevy::prelude::Name`.
#[component]
pub struct Name(pub String);

//! Graph types for mod developers.
//!
//! Binary-compatible with `paiagram_core::graph::NodeCoor` and
//! `paiagram_core::graph::Node`.

use bevy_moder_sdk::component;

/// Geographic coordinates (WGS84).  Binary-compatible with
/// `paiagram_core::graph::NodeCoor`.
#[component]
pub struct NodeCoor {
    pub lon: f64,
    pub lat: f64,
}

/// Graph node attached to a station.  Binary-compatible with
/// `paiagram_core::graph::Node`.
#[component]
pub struct Node {
    pub coor: NodeCoor,
}

