/// Manual `Name` registration for mod use.
/// `bevy::prelude::Name` can't carry `#[register_component]` directly
/// because it lives in the bevy crate, so we register it via ctor.
#[allow(non_snake_case)]
#[::bevy_moder_runtime::ctor::ctor]
fn __mod_register_mod_name() {
    component::register_component(
        "Name",
        |ptr: bevy::ptr::Ptr<'_>| {
            let name = unsafe { ptr.deref::<Name>() };
            ::bincode::serde::encode_to_vec(&name.0, ::bincode::config::standard())
                .unwrap_or_default()
        },
        |data: &[u8]| {
            let (s, _): (String, _) =
                ::bincode::serde::decode_from_slice(data, ::bincode::config::standard())
                    .expect("Name deserialize");
            Box::new(Name::new(&s))
        },
        || std::any::TypeId::of::<Name>(),
        |registry: &mut bevy::reflect::TypeRegistry| {
            registry.register::<Name>();
        },
        |entity: &mut bevy::ecs::world::EntityWorldMut, component: Box<dyn std::any::Any>| {
            if let Ok(c) = component.downcast::<Name>() {
                entity.insert(c.clone());
            }
        },
    );
}

/// Add newly-spawned station entities to the Graph resource.
pub(crate) fn register_new_stations(
    new_stations: Query<Entity, (Added<Station>, Without<IsExternalStation>, Without<IsDepot>)>,
    mut graph: ResMut<Graph>,
) {
    for entity in &new_stations {
        graph.add_node(entity);
    }
}

