/// Manual registration for mod-accessible native component types.
/// `Station` and `Node` already have `Reflect` in their derives, and
/// `#[register_component]` would add a conflicting second `Reflect` derive.
/// `Name` lives in the bevy crate so it can't carry the macro at all.
#[allow(non_snake_case)]
#[::bevy_moder_runtime::ctor::ctor]
fn __mod_register_native_components() {
    // ── Station (unit struct, zero bytes) ──
    component::register_component(
        "Station",
        |_ptr: bevy::ptr::Ptr<'_>| Vec::new(),
        |_data: &[u8]| Box::new(Station::default()),
        || std::any::TypeId::of::<Station>(),
        |registry: &mut bevy::reflect::TypeRegistry| {
            registry.register::<Station>();
        },
        |entity: &mut bevy::ecs::world::EntityWorldMut, component: Box<dyn std::any::Any>| {
            if let Ok(c) = component.downcast::<Station>() {
                entity.insert(*c);
            }
        },
    );

    // ── Node (lon / lat as f64 pair) ──
    component::register_component(
        "Node",
        |ptr: bevy::ptr::Ptr<'_>| {
            let n = unsafe { ptr.deref::<paiagram_core::graph::Node>() };
            ::bincode::serde::encode_to_vec(
                &(n.coor.lon, n.coor.lat),
                ::bincode::config::standard(),
            )
            .unwrap_or_default()
        },
        |data: &[u8]| {
            let (lon, lat): (f64, f64) =
                ::bincode::serde::decode_from_slice(data, ::bincode::config::standard())
                    .expect("Node deserialize");
            Box::new(paiagram_core::graph::Node {
                coor: paiagram_core::graph::NodeCoor::new(lon, lat),
            })
        },
        || std::any::TypeId::of::<paiagram_core::graph::Node>(),
        |registry: &mut bevy::reflect::TypeRegistry| {
            registry.register::<paiagram_core::graph::Node>();
        },
        |entity: &mut bevy::ecs::world::EntityWorldMut, component: Box<dyn std::any::Any>| {
            if let Ok(c) = component.downcast::<paiagram_core::graph::Node>() {
                entity.insert(*c);
            }
        },
    );

    // ── Name (bevy built-in, string wrapper) ──
    component::register_component(
        "Name",
        |ptr: bevy::ptr::Ptr<'_>| {
            let name = unsafe { ptr.deref::<Name>() };
