use bevy::log::*;
use bevy::prelude::*;
use std::any::Any;
use std::collections::{HashMap, HashSet};
use std::sync::Mutex;

/// Type-erased registration for one event type.
#[derive(Clone)]
pub struct EventRegistration {
    pub type_name: &'static str,
    /// Serialise a `&dyn Any` (the concrete event) into `Vec<u8>`.
    pub serialize_fn: fn(&(dyn Any + Send + Sync)) -> Vec<u8>,
    /// Deserialise bytes back into a `Box<dyn Any + Send + Sync>`.
    pub deserialize_fn: fn(&[u8]) -> Box<dyn Any + Send + Sync>,
    /// Trigger the event from bytes: calls `world.trigger(event)`.
    pub trigger_fn: fn(&mut World, Vec<u8>),
    /// Add a global observer that pushes serialised events into
    /// [`EventBuffer`] so mods can poll them via `on_event!`.
    pub add_observer_fn: fn(&mut World),
}

static EVENT_REGS: Mutex<Vec<EventRegistration>> = Mutex::new(Vec::new());

/// Register an event type (called from `#[register_event]` ctors).
pub fn register_event(reg: EventRegistration) {
    EVENT_REGS.lock().unwrap().push(reg);
}

/// Find a registration by type name.
pub fn find_event_registration(name: &str) -> Option<EventRegistration> {
    EVENT_REGS
        .lock()
        .unwrap()
        .iter()
        .find(|r| r.type_name == name)
        .cloned()
}

/// Iterate all registered event types.
pub fn iter_events() -> Vec<EventRegistration> {
    EVENT_REGS.lock().unwrap().clone()
}

/// Track which event types already have observers installed.
static OBSERVER_INSTALLED: std::sync::LazyLock<Mutex<HashSet<String>>> =
    std::sync::LazyLock::new(|| Mutex::new(HashSet::new()));

/// Install observers for every registered event that does not yet have one.
///
/// Safe to call multiple times — each event type only gets one observer.
pub fn install_missing_observers(world: &mut World) {
    let mut installed = OBSERVER_INSTALLED.lock().unwrap();
    for reg in iter_events() {
        if installed.insert(reg.type_name.to_string()) {
            info!("[bevy-moder] adding observer for event '{}'", reg.type_name);
            (reg.add_observer_fn)(world);
        }
    }
}

/// Buffer that stores serialised events queued by observers for mod polling.
#[derive(Resource, Default)]
pub struct EventBuffer {
    /// type_name → list of serialised pending events (FIFO order).
    pub pending: HashMap<String, Vec<Vec<u8>>>,
}

/// Two-phase read: `output == 0` returns the buffer size; `output != 0`
/// copies the bytes out.  Returns the payload length (or -1 on error).
///
/// After reading, the buffered event is **consumed** (popped from the queue).
pub fn host_handle_read_event(
    mut caller: wasmtime::Caller<'_, crate::ModState>,
    name_ptr: i32,
    name_len: i32,
    output: i32,
    out_len: i32,
) -> i32 {
    let memory = match caller.get_export("memory") {
        Some(e) => e.into_memory().unwrap(),
        None => return -1,
    };

    // Read type name
    let mut name_buf = vec![0u8; name_len as usize];
    if memory
        .read(&caller, name_ptr as usize, &mut name_buf)
        .is_err()
    {
        error!("read_event: failed to read type name");
        return -1;
    }
    let type_name = match String::from_utf8(name_buf) {
        Ok(s) => s,
        Err(_) => return -1,
    };

    let world = match caller.data().get_world() {
        Some(w) => w,
        None => return -1,
    };

    // Phase 1: return size
    if output == 0 {
        unsafe {
            let world_mut = world.world_mut();
            let buffer = world_mut.get_resource::<EventBuffer>();
            let buffer = match buffer {
                Some(b) => b,
                None => return -1,
            };
            let payload = match buffer.pending.get(&type_name) {
                Some(list) if !list.is_empty() => &list[0],
                _ => return -1,
            };
            let len: i32 = payload.len() as i32;
            let len_bytes = i32::to_le_bytes(len);
            if memory
                .write(&mut caller, out_len as usize, &len_bytes)
                .is_err()
            {
                error!("read_event: failed to write size");
                return -1;
            }
            len
        }
    } else {
        // Phase 2: read and consume
        unsafe {
            let world_mut = world.world_mut();
            let mut buffer = match world_mut.get_resource_mut::<EventBuffer>() {
                Some(b) => b,
                None => return -1,
            };
            let list = match buffer.pending.get_mut(&type_name) {
                Some(l) => l,
                None => return -1,
            };
            let payload = match list.get(0) {
                Some(p) => p.clone(),
                None => return -1,
            };
            let len = payload.len();
            if memory
                .write(&mut caller, output as usize, &payload)
                .is_err()
            {
                error!("read_event: failed to write output");
                return -1;
            }
            let len_bytes = i32::to_le_bytes(len as i32);
            if memory
                .write(&mut caller, out_len as usize, &len_bytes)
                .is_err()
            {
                error!("read_event: failed to write size");
                return -1;
            }
            // Consume the event
            list.remove(0);
            len as i32
        }
    }
}

/// Receive a serialised event from the WASM mod, deserialise it, and
/// trigger it on the host world so that all registered observers fire.
pub fn host_handle_trigger_event(
    mut caller: wasmtime::Caller<'_, crate::ModState>,
    name_ptr: i32,
    name_len: i32,
    data_ptr: i32,
    data_len: i32,
) -> i32 {
    let memory = match caller.get_export("memory") {
        Some(e) => e.into_memory().unwrap(),
        None => return -1,
    };

    // Read type name
    let mut name_buf = vec![0u8; name_len as usize];
    if memory
        .read(&caller, name_ptr as usize, &mut name_buf)
        .is_err()
    {
        error!("trigger_event: failed to read type name");
        return -1;
    }
    let type_name = match String::from_utf8(name_buf) {
        Ok(s) => s,
        Err(_) => return -1,
    };

    // Read serialised data
    let mut data_buf = vec![0u8; data_len as usize];
    if memory
        .read(&caller, data_ptr as usize, &mut data_buf)
        .is_err()
    {
        error!("trigger_event: failed to read data");
        return -1;
    }

    let world = match caller.data().get_world() {
        Some(w) => w,
        None => return -1,
    };

    let registration = match find_event_registration(&type_name) {
        Some(r) => r,
        None => {
            error!(
                "trigger_event: no registration for '{}', dropping event",
                type_name,
            );
            return -1;
        }
    };

    unsafe {
        let mut world_mut = world.world_mut();
        (registration.trigger_fn)(&mut world_mut, data_buf);
    }

    0
}

